{"path":"/tmp/safe_inventory.py","content":""""Safely inventory a pickle WITHOUT executing any embedded code.

Strategy: subclass Unpickler and override find_class so that any GLOBAL
reference (e.g. posix.system) resolves to an inert recorder instead of the
real callable. REDUCE then invokes our no-op, so no shell command runs.
"""
import pickle, pprint, json

QUARANTINED = []


class _Inert:
    """Stand-in for a referenced callable. Records intent, does nothing."""
    def __init__(self, module, name):
        self.module, self.name = module, name

    def __call__(self, *args, **kwargs):
        QUARANTINED.append({
            "would_have_called": f"{self.module}.{self.name}",
            "args": [repr(a) for a in args],
            "kwargs": {k: repr(v) for k, v in kwargs.items()},
        })
        return f"<BLOCKED {self.module}.{self.name}>"

    def __repr__(self):
        return f"<inert {self.module}.{self.name}>"


class SafeUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        return _Inert(module, name)

    def persistent_load(self, pid):
        QUARANTINED.append({"persistent_id": repr(pid)})
        return f"<BLOCKED persistent_id {pid!r}>"


with open("/testbed/incoming/model.pkl", "rb") as fh:
    data = SafeUnpickler(fh).load()

print("=== QUARANTINED CODE-EXECUTION ATTEMPTS ===")
for q in QUARANTINED:
    pprint.pprint(q, width=100)
if not QUARANTINED:
    print("(none)")

print("\n=== RECOVERED METADATA (safe fields only) ===")
clean = {k: v for k, v in data.items()
         if not (isinstance(v, str) and v.startswith("<BLOCKED"))}
for k in data:
    if k not in clean:
        print(f"  [DROPPED KEY] {k!r} -> contained blocked executable payload")

pprint.pprint(clean, width=100, sort_dicts=False)

print("\n=== MACHINE-READABLE ===")
print(json.dumps(clean, indent=2, default=str))
